UPDATE funding_sync_request
SET state = 'READY', current_run_id = NULL
WHERE id = #{id} AND state = 'RUNNING' AND current_run_id = #{runId}

UPDATE funding_sync_request
SET state = 'SUCCEEDED', current_run_id = NULL, successful_run_id = #{runId}
WHERE id = #{id} AND state = 'RUNNING' AND current_run_id = #{runId}
